const app = document.querySelector('#app');
const money = cents => new Intl.NumberFormat('en-US', {style:'currency',currency:'USD'}).format(cents/100);
const esc = value => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const icon = (name, size=19) => {
  const common = `class="ui-icon" style="--icon-size:${size}px" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"`;
  const shapes = {
    arrow:'<path d="M4 12h16m-7-7 7 7-7 7"/>',
    arrowLeft:'<path d="M20 12H4m7-7-7 7 7 7"/>',
    northeast:'<path d="M5 19 19 5M6 5h13v13"/>',
    bag:'<path d="M4 8h16l-1.2 13H5.2L4 8Z"/><path d="M9 9V6a3 3 0 0 1 6 0v3"/>',
    search:'<circle cx="10.9" cy="10.9" r="6.5"/><path d="m16 16 5 5"/>',
    menu:'<path d="M3 7h18M3 17h18"/>',
    close:'<path d="M5 5 19 19M19 5 5 19"/>',
    plus:'<path d="M5 12h14M12 5v14"/>',
    minus:'<path d="M5 12h14"/>',
    chevron:'<path d="m6 9 6 6 6-6"/>',
    check:'<path d="m4 12 5 5L20 6"/>',
    shield:'<path d="M12 2 4 6v6c0 5 3 8.5 8 10 5-1.5 8-5 8-10V6l-8-4Z"/><path d="m9 12 2 2 4-4"/>',
    minusCircle:'<circle cx="12" cy="12" r="9"/><path d="M8 12h8"/>'
  };
  return `<svg ${common}>${shapes[name]||shapes.arrow}</svg>`;
};
const symbol = `<svg viewBox="0 0 62 62" class="brand-symbol" aria-hidden="true"><path d="M31 3 2 58h13L31 25l16 33h13L31 3Z" fill="currentColor"/><path d="M24 47h14l6 11H18l6-11Z" fill="currentColor"/></svg>`;
let products = [];
const canBuy = p => Boolean(p && ((p.inStock && p.priceConfirmed && p.labelVerified) || (p.demoAvailable && (config.mode==='demo' || !p.isSample))));
const stockLabel = p => p.isConcept ? 'Collection preview · details pending' : p.isSample ? 'Sample listing · not live inventory' : p.inStock ? 'In stock · confirmed inventory' : p.demoAvailable ? 'Preview product · sales not open yet' : 'Currently unavailable';
let config = {mode:'demo',storeLive:false,preview:true,supportEmail:'',store:{policies:{}}};
const preview = () => config.preview;
const supportLink = () => config.supportEmail?`<a href="mailto:${esc(config.supportEmail)}">${esc(config.supportEmail)}</a>`:'our support team';
const FDA = 'These statements have not been evaluated by the Food and Drug Administration. This product is not intended to diagnose, treat, cure, or prevent any disease.';
const priceLabel = p => p.isConcept?'Preview price':p.isSample?'Sample price':!p.priceConfirmed?'Preview price':'';
let cart = loadCart();
let view = {cartOpen:false,menuOpen:false,detailQty:1,galleryIndex:0,toast:'',toastTimer:null,checkoutLoading:false};
const byId = id => products.find(p => p.id === id);
const count = () => cart.reduce((sum,item)=>sum+item.qty,0);
const total = () => cart.reduce((sum,item)=>sum + (byId(item.id)?.priceCents||0)*item.qty,0);
function loadCart(){try { const data=JSON.parse(localStorage.getItem('auctoran-cart-v1')||'[]'); return Array.isArray(data)?data.filter(i=>i&&typeof i.id==='string'&&Number.isInteger(i.qty)&&i.qty>0).slice(0,30):[]; } catch { return []; }}
function saveCart(){try{localStorage.setItem('auctoran-cart-v1',JSON.stringify(cart))}catch{/* cart remains available in current session */}}
function scrollToDestination(){
 const hash=location.hash.slice(1);let target=null;
 if(hash){try{target=document.getElementById(decodeURIComponent(hash));}catch{/* invalid fragments return to the page top */}}
 if(target){target.scrollIntoView({block:'start'});target.setAttribute('tabindex','-1');target.focus({preventScroll:true});}
 else window.scrollTo({top:0,behavior:'instant'});
}
function navigate(url){
 history.pushState({},'',url);view.menuOpen=false;view.cartOpen=false;view.detailQty=1;view.galleryIndex=0;view.checkoutLoading=false;
 render();document.querySelector('main')?.focus({preventScroll:true});scrollToDestination();
}
function notify(message){view.toast=message;refreshShell();clearTimeout(view.toastTimer);view.toastTimer=setTimeout(()=>{view.toast='';refreshShell();},3600);}
function addCart(id,qty=1){const product=byId(id);if(!product)return;if(!canBuy(product)){notify(`${product.name} is sold out.`);return;}const existing=cart.find(i=>i.id===id);if(existing)existing.qty+=qty;else cart.push({id,qty});cart=normalizeCart(cart,products);saveCart();view.cartOpen=true;refreshShell();}
function changeCart(id,delta){const item=cart.find(i=>i.id===id);if(!item)return;item.qty=Math.max(0,Math.min(20,item.qty+delta));cart=normalizeCart(cart.filter(i=>i.qty>0),products);saveCart();refreshShell();if(location.pathname==='/cart')render();}
function removeCart(id){cart=cart.filter(i=>i.id!==id);saveCart();refreshShell();if(location.pathname==='/cart')render();}
function galleryPhoto(photo,{hero=false}={}){
  const fortivor = /fortivor-studio-front\.webp$/.test(photo.src);
  const campaign = /\/(studio-|collection-|editorial-|campaign-)/.test(photo.src);
  const sizes=esc(photo.sizes||'(max-width:700px) 94vw, 50vw');
  const responsive = fortivor ? `srcset="${photo.src.replace('.webp','-mobile.webp')} 768w, ${photo.src} 1254w" sizes="${sizes}"` : campaign ? `srcset="${photo.src.replace('.webp','-mobile.webp')} ${photo.src.includes('/campaign-')?768:640}w, ${photo.src} ${photo.width||1280}w" sizes="${sizes}"` : '';
  return `<img ${responsive} width="${photo.width||(fortivor?1254:1280)}" height="${photo.height||(fortivor?1254:/\/(studio|collection)-/.test(photo.src)?1280:853)}" decoding="async" src="${esc(photo.src)}" alt="${esc(photo.alt)}" ${hero?'fetchpriority="high"':'loading="lazy"'} class="real-product-img"/>`;
}
function productGallery(p){
  return p.gallery?.length ? p.gallery : [{src:p.image,label:'Product',alt:`${p.fullName} by ${p.brand}`}];
}
function productImage(p,{hero=false,sizes='(max-width:700px) 44vw, 30vw'}={}){
  if(p.image) return galleryPhoto({...p.gallery?.[0],src:p.image,alt:p.gallery?.[0]?.alt||`${p.fullName} by ${p.brand}`,sizes},{hero});
  return '<div class="image-pending" role="img" aria-label="Product photography awaiting confirmation">PRODUCT IMAGE PENDING</div>';
}
