function comparisonSection(product){
 const {products:compared,advantages}=buildComparison(product);
 const own=compared[0],ghost=compared.find(p=>p.id==='ghost'),c4=compared.find(p=>p.id==='c4');
 const grams=value=>Number.isFinite(value)?value/1000:'Pending';
 const rows=[['L-Citrulline','citrullineMg'],['Beta-Alanine','betaAlanineMg'],['Betaine Anhydrous','betaineMg'],['Servings at dose shown','dosesPerTub']];
 const amount=(p,key)=>p[key]===null?(p.id==='fortivor'?'Pending':'Not listed'):key==='dosesPerTub'?p[key]:`${p[key]/1000} g`;
 return `<section class="product-comparison" id="compare" tabindex="-1" aria-labelledby="compare-title"><div class="comparison-intro"><p class="kicker">WHY FORTIVOR</p><h2 id="compare-title">The numbers.<br/><em>Side by side.</em></h2><p>Big names. Same table. See where Fortivor brings more.</p></div><div class="comparison-wins">${advantages.citrullineVsGhostPercent?`<article><strong>${advantages.citrullineVsGhostPercent}<span>%</span></strong><p>more L-citrulline<br/><b>than GHOST Legend V5</b></p><span>${grams(own.citrullineMg)} g vs. ${grams(ghost.citrullineMg)} g per compared serving</span></article>`:''}${advantages.betaineVsC4Multiple?`<article><strong>${advantages.betaineVsC4Multiple}<span>×</span></strong><p>the betaine<br/><b>of C4 Ultimate</b></p><span>${grams(own.betaineMg)} g vs. ${grams(c4.betaineMg)} g per compared serving</span></article>`:''}<aside><p>${grams(own.citrullineMg)} g L-citrulline.<br/>${grams(own.betaAlanineMg)} g beta-alanine.<br/>${grams(own.betaineMg)} g betaine.</p><span>Our proposed amounts. In one Fortivor scoop.</span><a href="/product/fortivor-pre-workout#formula" data-route>KNOW THE FORMULA ${icon('arrow',16)}</a></aside></div><p id="comparison-help" class="comparison-help">Compare the dose, not just the tub. <span>Scroll the table to see every brand ${icon('arrow',14)}</span></p><div class="comparison-scroll" role="region" aria-label="Pre-workout ingredient comparison" tabindex="0" aria-describedby="comparison-help comparison-note"><table class="comparison-table"><caption>Selected ingredient amounts per compared dose</caption><thead><tr><th scope="col">WHAT’S INSIDE</th>${compared.map(p=>`<th scope="col" class="${p.id==='fortivor'?'our-formula':''}">${p.id==='fortivor'?'<span class="comparison-pick">AUCTORAN LABS</span>':''}<strong>${esc(p.name)}</strong><small>${p.scoops} ${p.scoops===1?'scoop':'scoops'}${p.id==='gorilla'?' · maximum dose':p.id==='fortivor'?' · proposed':''}</small></th>`).join('')}</tr></thead><tbody>${rows.map(([name,key])=>`<tr><th scope="row">${name}</th>${compared.map(p=>`<td data-brand="${p.id}" data-metric="${key}" class="${p.id==='fortivor'?'our-formula':''}">${amount(p,key)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p id="comparison-note" class="comparison-note">Fortivor figures are proposed specifications pending final production verification. Gorilla Mode is shown at its two-scoop maximum: its label also lists 40 one-scoop servings with half the amounts. Other active ingredients differ.</p><details class="comparison-sources"><summary>Sources & comparison details ${icon('plus',16)}</summary><div><p>Official labels checked ${COMPARISON_CHECKED}. Specific versions compared:</p><ul>${BENCHMARKS.map(p=>`<li><a href="${p.productUrl}" target="_blank" rel="noopener noreferrer">${p.name} — ${p.variant}</a> · <a href="${p.labelUrl}" target="_blank" rel="noopener noreferrer">View label</a></li>`).join('')}</ul><p>This compares selected ingredient quantities, not complete formulas or results from head-to-head workout testing. More of one ingredient alone does not establish superior performance. Fortivor’s final label, serving weight, total caffeine and availability still require verification.</p></div></details></section>`;
}
