 return `<div class="detail-main-image ${photos[index].kind==='label'?'flat-label-view':''}"><button type="button" class="detail-gallery-image" data-action="zoomGallery" data-id="${esc(p.id)}" aria-label="Enlarge ${esc(photos[index].label)}">${galleryPhoto(photos[index],{hero:true})}<span class="zoom-hint">${icon('plus',17)} ENLARGE IMAGE</span></button>${p.isConcept?'<span class="detail-demo-tag">AUCTORAN LABS / DESIGN CONCEPT</span>':p.isSample?'<span class="detail-demo-tag">ILLUSTRATIVE CATEGORY IMAGE / SAMPLE LISTING</span>':''}</div>${photos.length>1?`<div class="gallery-tools"><span>${String(index+1).padStart(2,'0')} / ${String(photos.length).padStart(2,'0')}</span><span>SWIPE TO EXPLORE</span><div><button type="button" aria-label="Previous image" data-action="galleryPrevious" data-id="${esc(p.id)}">${icon('arrowLeft',18)}</button><button type="button" aria-label="Next image" data-action="galleryNext" data-id="${esc(p.id)}">${icon('arrow',18)}</button></div></div><div class="detail-image-row" role="group" aria-label="${esc(p.name)} gallery">${photos.map((photo,i)=>`<button type="button" data-action="showDetailImage" data-id="${esc(p.id)}" data-photo="${i}" aria-pressed="${i===index}" aria-label="View ${esc(photo.label)}">${galleryPhoto(photo)}<span class="gallery-photo-label">${esc(photo.label)}</span></button>`).join('')}</div>`:''}<p class="gallery-caption" aria-live="polite">${esc(photos[index].alt)}</p>`;
