function adminToken(){try{return sessionStorage.getItem('auctoran-admin')||'';}catch{return '';}}
function adminPage(){return `<main class="info-page admin-page"><p class="kicker">MANAGE ORDERS</p><h1>ORDERS<em>.</em></h1>${adminToken()?'<div id="admin-orders" class="admin-orders">Loading orders…</div><button class="remove-link" data-action="adminLogout">SIGN OUT</button>':'<form id="admin-login" class="admin-login"><label for="admin-token">ADMIN TOKEN</label><input id="admin-token" type="password" autocomplete="current-password" required/><button class="btn dark-btn" type="submit">VIEW ORDERS</button></form>'}</main>`;}
async function adminFetch(url,options={}){const res=await fetch(url,{...options,headers:{...options.headers,Authorization:'Bearer '+adminToken()}});const data=await res.json();if(res.status===401){try{sessionStorage.removeItem('auctoran-admin')}catch{}render();throw new Error('Invalid admin token');}if(!res.ok)throw new Error(data.error||'Request failed');return data;}
function addressText(a={}){return [a.line1,a.line2,[a.city,a.state,a.postal_code].filter(Boolean).join(' '),a.country].filter(Boolean).map(esc).join('<br/>');}
